def minPath(grid: List[List[int]], k: int) -> List[int]:
    N = len(grid)
    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]
    visited = [[False] * N for _ in range(N)]

    def dfs(x: int, y: int, path: List[int], steps: int):
        nonlocal min_path
        if steps == k:
            if not min_path or path < min_path:
                min_path = path.copy()
            return

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N and not visited[nx][ny]:
                visited[nx][ny] = True
                path.append(grid[nx][ny])
                dfs(nx, ny, path, steps + 1)
                path.pop()
                visited[nx][ny] = False

    min_path = None
    for i in range(N):
        for j in range(N):
            visited[i][j] = True
            dfs(i, j, [grid[i][j]], 1)
            visited[i][j] = False

    return min_path

