    balance = 0
    for char in brackets:
        if char == '(':
            balance += 1
        elif char == ')':
            balance -= 1
        # If balance goes negative, there's a closing bracket without an opening bracket
        if balance < 0:
            return False
    # At the end, balance should be zero for correct matching
    return balance == 0

