def fib4(n: int) -> int:
    # Base cases
    if n == 0 or n == 1:
        return 0
    elif n == 2:
        return 2
    elif n == 3:
        return 0

    # Initialize the first four values of the sequence
    fib_values = [0, 0, 2, 0]

    # Compute the n-th value iteratively
    for i in range(4, n + 1):
        next_value = sum(fib_values)  # Sum of the last four values
        fib_values.pop(0)  # Remove the oldest value
        fib_values.append(next_value)  # Add the new value

    return fib_values[-1]

