                visited[nx][ny] = True
                path.append(grid[nx][ny])
                dfs(nx, ny, path, steps + 1)
                path.pop()
                visited[nx][ny] = False

    min_path = None
    for i in range(N):
        for j in range(N):
            visited[i][j] = True
            dfs(i, j, [grid[i][j]], 1)
